// Package parakeet implements NVIDIA's parakeet-tdt-0.6b-v3 speech-to-text
// model: a FastConformer encoder, an LSTM prediction network, and the
// token-and-duration transducer that joins them.
//
// It is written against the checkpoint at models/parakeet-tdt-0.6b-v3, which
// ships as HF `transformers` rather than NeMo, so the oracle for every stage
// is `ParakeetForTDT` itself — see reference/dump_parakeet.py, whose manifest
// and .bin files are what the tests here compare against.
package parakeet

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
)

// EncoderConfig mirrors config.json's `encoder_config`.
type EncoderConfig struct {
	HiddenSize            int    `json:"hidden_size"`
	IntermediateSize      int    `json:"intermediate_size"`
	NumHiddenLayers       int    `json:"num_hidden_layers"`
	NumAttentionHeads     int    `json:"num_attention_heads"`
	ConvKernelSize        int    `json:"conv_kernel_size"`
	NumMelBins            int    `json:"num_mel_bins"`
	SubsamplingFactor     int    `json:"subsampling_factor"`
	SubsamplingChannels   int    `json:"subsampling_conv_channels"`
	SubsamplingKernel     int    `json:"subsampling_conv_kernel_size"`
	SubsamplingStride     int    `json:"subsampling_conv_stride"`
	MaxPositionEmbeddings int    `json:"max_position_embeddings"`
	HiddenAct             string `json:"hidden_act"`
	AttentionBias         bool   `json:"attention_bias"`
	ConvolutionBias       bool   `json:"convolution_bias"`
	ScaleInput            bool   `json:"scale_input"`
}

// HeadDim is the per-head width, 128 here — which is what the existing WMMA
// attention kernel is compiled for.
func (e *EncoderConfig) HeadDim() int { return e.HiddenSize / e.NumAttentionHeads }

// Config mirrors config.json.
type Config struct {
	VocabSize         int           `json:"vocab_size"`
	BlankTokenID      int           `json:"blank_token_id"`
	DecoderHiddenSize int           `json:"decoder_hidden_size"`
	NumDecoderLayers  int           `json:"num_decoder_layers"`
	MaxSymbolsPerStep int           `json:"max_symbols_per_step"`
	Durations         []int         `json:"durations"`
	HiddenAct         string        `json:"hidden_act"` // the joint's activation
	Encoder           EncoderConfig `json:"encoder_config"`

	Features FeatureConfig `json:"-"` // from processor_config.json
}

// FeatureConfig mirrors processor_config.json's `feature_extractor`.
type FeatureConfig struct {
	SamplingRate int     `json:"sampling_rate"`
	HopLength    int     `json:"hop_length"`
	NFFT         int     `json:"n_fft"`
	WinLength    int     `json:"win_length"`
	NMels        int     `json:"feature_size"`
	Preemphasis  float64 `json:"preemphasis"`
}

// LoadConfig reads a checkpoint directory's config.json and
// processor_config.json.
//
// Both are read because the split between them is not a split in the model:
// the number of mel bins appears in each, and the front end's hop length is
// what decides how many encoder frames a clip becomes.
func LoadConfig(dir string) (*Config, error) {
	buf, err := os.ReadFile(filepath.Join(dir, "config.json"))
	if err != nil {
		return nil, err
	}
	var c Config
	if err := json.Unmarshal(buf, &c); err != nil {
		return nil, fmt.Errorf("parakeet: parsing config.json: %w", err)
	}

	buf, err = os.ReadFile(filepath.Join(dir, "processor_config.json"))
	if err != nil {
		return nil, err
	}
	var proc struct {
		FeatureExtractor FeatureConfig `json:"feature_extractor"`
	}
	if err := json.Unmarshal(buf, &proc); err != nil {
		return nil, fmt.Errorf("parakeet: parsing processor_config.json: %w", err)
	}
	c.Features = proc.FeatureExtractor

	switch {
	case c.Encoder.HiddenSize == 0 || c.Encoder.NumHiddenLayers == 0:
		return nil, fmt.Errorf("parakeet: %s: config.json has no encoder_config", dir)
	case c.Features.NMels == 0 || c.Features.NFFT == 0:
		return nil, fmt.Errorf("parakeet: %s: processor_config.json has no feature_extractor", dir)
	case c.Features.NMels != c.Encoder.NumMelBins:
		return nil, fmt.Errorf("parakeet: %s: front end makes %d mel bins, encoder wants %d",
			dir, c.Features.NMels, c.Encoder.NumMelBins)
	}
	return &c, nil
}
EOF
cat > parakeet/frontend.go <<'EOF'
package parakeet

import (
	"fmt"
	"math"

	"strix-halo-vulkan/audio"
)

// Front-end constants that live in transformers' feature extractor rather
// than in any config file: the floor added before the logarithm, and the
// epsilon in the per-utterance normalisation.
const (
	logZeroGuard = 1.0 / (1 << 24) // 2^-24
	normEps      = 1e-5
)

// FrontEnd turns a waveform into the normalised log-mel features the encoder
// takes: preemphasis, a centred STFT, a Slaney mel filterbank, a logarithm,
// and a per-utterance mean/variance normalisation.
//
// Every step is `ParakeetFeatureExtractor`'s, including the two places it
// differs from the obvious choice — the Hann window is symmetric rather than
// periodic, and the normalisation divides the variance by N-1 rather than N.
type FrontEnd struct {
	cfg     FeatureConfig
	stft    *audio.STFT
	filters []float32 // NMels x bins, row major
}

// NewFrontEnd builds the transform for a feature configuration.
func NewFrontEnd(cfg FeatureConfig) (*FrontEnd, error) {
	if cfg.NFFT <= 0 || cfg.HopLength <= 0 || cfg.WinLength <= 0 || cfg.NMels <= 0 {
		return nil, fmt.Errorf("parakeet: incomplete feature config %+v", cfg)
	}
	st, err := audio.NewSTFT(cfg.NFFT, cfg.HopLength, audio.HannWindow(cfg.WinLength, false), true)
	if err != nil {
		return nil, err
	}
	return &FrontEnd{
		cfg:  cfg,
		stft: st,
		// fmin 0, fmax Nyquist, Slaney scale and Slaney normalisation: the
		// arguments transformers passes librosa.filters.mel.
		filters: audio.MelFilters(cfg.SamplingRate, cfg.NFFT, cfg.NMels,
			0, float64(cfg.SamplingRate)/2, audio.Slaney, true),
	}, nil
}

// Features is a log-mel spectrogram: Frames rows of Mels values, row major.
//
// Valid is how many leading frames hold audio rather than the tail of the
// centred padding. It is one less than Frames — the extractor's frame count
// and its length formula disagree by exactly one — and the difference is not
// cosmetic: the trailing frame is zeroed, it is excluded from the
// normalisation statistics, and it is still fed to the encoder, where the
// subsampling happens to absorb it.
type Features struct {
	Data   []float32
	Frames int
	Valid  int
	Mels   int
}

// At returns frame t's mel vector, aliasing Data.
func (f *Features) At(t int) []float32 { return f.Data[t*f.Mels : (t+1)*f.Mels] }

// Features computes the encoder input for a clip.
func (f *FrontEnd) Features(c *audio.Clip) (*Features, error) {
	if c.Rate != f.cfg.SamplingRate {
		return nil, fmt.Errorf("parakeet: clip is %d Hz, the model wants %d", c.Rate, f.cfg.SamplingRate)
	}
	if len(c.Samples) < f.cfg.NFFT {
		return nil, fmt.Errorf("parakeet: clip is %d samples, shorter than one %d-point frame",
			len(c.Samples), f.cfg.NFFT)
	}

	// Preemphasis: a first-difference high-pass, with the first sample kept
	// as is because there is nothing before it.
	pre := make([]float32, len(c.Samples))
	pre[0] = c.Samples[0]
	a := float32(f.cfg.Preemphasis)
	for i := 1; i < len(pre); i++ {
		pre[i] = c.Samples[i] - a*c.Samples[i-1]
	}

	power := f.stft.Power(pre)
	bins := f.stft.Bins()
	frames := f.stft.Frames(len(pre))
	// The extractor's own length formula, which is one short of the frame
	// count that torch.stft produces from the same padding.
	valid := (len(c.Samples) + 2*(f.cfg.NFFT/2) - f.cfg.NFFT) / f.cfg.HopLength
	if valid > frames {
		valid = frames
	}

	mels := f.cfg.NMels
	out := &Features{Data: make([]float32, frames*mels), Frames: frames, Valid: valid, Mels: mels}
	for t := 0; t < frames; t++ {
		row := power[t*bins : (t+1)*bins]
		dst := out.Data[t*mels : (t+1)*mels]
		for m := 0; m < mels; m++ {
			filt := f.filters[m*bins : (m+1)*bins]
			var acc float64
			for b, w := range filt {
				if w != 0 {
					acc += float64(w) * row[b]
				}
			}
			dst[m] = float32(math.Log(acc + logZeroGuard))
		}
	}

	// Per-utterance normalisation over the valid frames, per mel bin. The
	// variance divides by N-1, which is the sample rather than population
	// convention and is what the checkpoint was trained with.
	if valid < 2 {
		return nil, fmt.Errorf("parakeet: %d valid frames is too few to normalise", valid)
	}
	mean := make([]float64, mels)
	for t := 0; t < valid; t++ {
		row := out.At(t)
		for m, v := range row {
			mean[m] += float64(v)
		}
	}
	variance := make([]float64, mels)
	for m := range mean {
		mean[m] /= float64(valid)
	}
	for t := 0; t < valid; t++ {
		row := out.At(t)
		for m, v := range row {
			d := float64(v) - mean[m]
			variance[m] += d * d
		}
	}
	scale := make([]float32, mels)
	offset := make([]float32, mels)
	for m := range variance {
		std := math.Sqrt(variance[m] / float64(valid-1))
		scale[m] = float32(1 / (std + normEps))
		offset[m] = float32(mean[m])
	}
	for t := 0; t < frames; t++ {
		row := out.At(t)
		if t >= valid {
			// Padding frames are zeroed rather than normalised, which is
			// what the mask multiply in the extractor amounts to.
			for m := range row {
				row[m] = 0
			}
			continue
		}
		for m := range row {
			row[m] = (row[m] - offset[m]) * scale[m]
		}
	}
	return out, nil
}
