	loadOnce  sync.Once
	sharedM   *Model
	sharedErr error
)

func testModel(t *testing.T) *Model {
	t.Helper()
	loadOnce.Do(func() { sharedM, sharedErr = Load(modelDir) })
	if sharedErr != nil {
