// 3e-4, and every stage amplifies that by whatever its weights do. The number
// that matters is therefore the *relative* one, printed against each stage's
// rms, and the bound below is read off the measured drift of the worst stage
// with an order of magnitude to spare. TestEncoderDetectsErrors pins the
// other side.
const encTol = 5e-2

func TestSubsamplingMatchesReference(t *testing.T) {
	m := testModel(t)
	ref := loadManifest(t)
