		if d.MaxAbs > encTol*d.RMS {
			t.Errorf("%s deviates by %.3g, which is more than %g of its rms %.4g", name, d.MaxAbs, encTol, d.RMS)
		}
		seen[c.Index] = true
	})
	if err != nil {
		t.Fatal(err)
